insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000920051', '20000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000001002', 'multiple_choice', 'medium', 'published', 'Durante uma revisão de código e hardware, a equipe precisa interpretar corretamente um conceito. Um colega usa essa ideia para justificar uma decisão. O comportamento típico de um flip-flop D na borda ativa do clock. Um estudante afirmou a opção destacada. Qual avaliação é adequada?') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
