insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) values ('70000000-0000-4000-8000-000009200991', '40000000-0000-4000-8000-000000920099', 'Identifique o foco', 'O enunciado trata de processador e instrucoes e pede uma interpretação conceitual.', 1), ('70000000-0000-4000-8000-000009200992', '40000000-0000-4000-8000-000000920099', 'Recupere a definição', 'A instrução precisa estar disponível antes de poder ser decodificada e executada.', 2), ('70000000-0000-4000-8000-000009200993', '40000000-0000-4000-8000-000000920099', 'Aplique ao caso', 'A informação relevante permite concluir: Lê da memória a instrução apontada pelo PC.', 3), ('70000000-0000-4000-8000-000009200994', '40000000-0000-4000-8000-000000920099', 'Elimine distrações', 'As outras alternativas representam confusões frequentes entre dados, endereço, estado, controle ou desempenho.', 4), ('70000000-0000-4000-8000-000009200995', '40000000-0000-4000-8000-000000920099', 'Verifique a conclusão', 'A resposta permanece coerente com a definição; portanto, a alternativa A é a correta.', 5) on conflict (id) do update set question_id=excluded.question_id, title=excluded.title, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.questions (id, subject_id, source_id, kind, difficulty, publication_status, statement_markdown) values ('40000000-0000-4000-8000-000000920100', '20000000-0000-4000-8000-000000000005', '10000000-0000-4000-8000-000000001002', 'multiple_choice', 'medium', 'published', 'Em uma questão de projeto, é importante distinguir termos próximos sem confundir suas funções. Um colega usa essa ideia para justificar uma decisão. A vantagem típica de uma ISA RISC. Qual alternativa está correta?') on conflict (id) do update set subject_id=excluded.subject_id, source_id=excluded.source_id, kind=excluded.kind, difficulty=excluded.difficulty, publication_status=excluded.publication_status, statement_markdown=excluded.statement_markdown;
insert into public.question_options (id, question_id, label, content_markdown, sort_order) values ('50000000-0000-4000-8000-000009201001', '40000000-0000-4000-8000-000000920100', 'A', 'Não precisa de registradores.', 1), ('50000000-0000-4000-8000-000009201002', '40000000-0000-4000-8000-000000920100', 'B', 'Não possui instruções de salto.', 2), ('50000000-0000-4000-8000-000009201003', '40000000-0000-4000-8000-000000920100', 'C', 'Usa memória apenas uma vez.', 3), ('50000000-0000-4000-8000-000009201004', '40000000-0000-4000-8000-000000920100', 'D', 'Instruções simples e regulares facilitam a implementação.', 4) on conflict (id) do update set question_id=excluded.question_id, label=excluded.label, content_markdown=excluded.content_markdown, sort_order=excluded.sort_order;
insert into public.question_answer_keys (question_id, correct_option_id) values ('40000000-0000-4000-8000-000000920100', '50000000-0000-4000-8000-000009201004') on conflict (question_id) do update set correct_option_id=excluded.correct_option_id;
